// src/services/credit.ts
async function getCreditBalanceForUser(bindings, userId) {
  const admin = createServiceRoleClient(bindings);
  const { data, error } = await admin.from("credit_balances").select(
    "id, user_id, balance, monthly_quota, monthly_used, reset_at, source, updated_at"
  ).eq("user_id", userId).maybeSingle();
  if (error) {
    console.error("credit_balances select failed");
    throw AppError.internal("Failed to load credit balance");
  }
  if (!data)
    return null;
  return mapCreditBalanceRow(data);
}
__name(getCreditBalanceForUser, "getCreditBalanceForUser");

// src/services/profile.ts
function resolveDisplayName(user) {
  const meta = user.user_metadata ?? {};
  const fromMeta = typeof meta.display_name === "string" && meta.display_name.trim() || typeof meta.name === "string" && meta.name.trim() || typeof meta.full_name === "string" && meta.full_name.trim();
  if (fromMeta)
    return fromMeta;
  const email = user.email?.trim();
  if (email) {
    const prefix = email.split("@")[0]?.trim();
    if (prefix)
      return prefix;
  }
  return "Writer";
}
__name(resolveDisplayName, "resolveDisplayName");
async function getOrCreateProfileForAuthUser(bindings, user) {
  const admin = createServiceRoleClient(bindings);
  const userId = user.id;
  const { data: existing, error: selectError } = await admin.from("profiles").select(
    "id, display_name, email, default_language, plan_label, role, subscription_plan, created_at, updated_at"
  ).eq("id", userId).maybeSingle();
  if (selectError) {
    console.error("profiles select failed");
    throw AppError.internal("Failed to load profile");
  }
  if (existing) {
    return mapProfileRow(existing);
  }
  const email = user.email?.trim() ?? "";
  const insertRow = {
    id: userId,
    email,
    display_name: resolveDisplayName(user),
    role: "writer",
    subscription_plan: "free"
  };
  const { data: created, error: insertError } = await admin.from("profiles").insert(insertRow).select(
    "id, display_name, email, default_language, plan_label, role, subscription_plan, created_at, updated_at"
  ).single();
  if (insertError || !created) {
    console.error("profiles insert failed");
    throw AppError.internal("Failed to create profile");
  }
  return mapProfileRow(created);
}
__name(getOrCreateProfileForAuthUser, "getOrCreateProfileForAuthUser");

// src/routes/me.ts
function registerMeRoutes(app) {
  app.get("/api/me", authMiddleware, async (c) => {
    const user = c.get("authUser");
    const profile = await getOrCreateProfileForAuthUser(c.env, user);
    const creditBalance = await getCreditBalanceForUser(c.env, user.id);
    const body = {
      user: {
        id: user.id,
        email: user.email ?? c.get("email")
      },
      profile,
      creditBalance
    };
    return jsonSuccess(c, body);
  });
}
__name(registerMeRoutes, "registerMeRoutes");

